 */
public record PermitView(
        String permitKey,
        String crewName,
        Instant workStartUtc,
        Instant workEndUtc,
        String applicant,
        String status,
        List<String> isolationKeys,
        List<ApprovalView> approvals,
        Instant createdAt,
        Instant closedAt) {
}

package com.example.starter.site.dto;

/**
 * 统一错误响应体。
 */
public record ApiError(String code, String message) {
}

