```java
private boolean covers(List<IsolationRow> isolations, long start, long end) {
    // intervals sorted by start; sweep
    List<long[]> intervals = isolations.stream().map(i -> new long[]{i.plannedStartUtc(), i.plannedEndUtc()}).sorted(...).toList();
    long cursor = start;
    for (long[] iv : intervals) {
        if (iv[1] <= cursor) continue;
        if (iv[0] > cursor) return false;
        cursor = Math.max(cursor, iv[1]);
        if (cursor >= end) return true;
    }
    return cursor >= end;
}
